#include <iostream>
#include <vector>
#include <atcoder/modint>

int main() {
    using namespace std;
    using modint = atcoder::static_modint<998244353>;
    unsigned N;
    cin >> N;
    vector<unsigned> Q(N);
    for (auto&& q : Q) {
        cin >> q;
        --q;
    }
    modint ans{1};
    vector<unsigned> prev_greater(N);
    for (unsigned i{1}; i < N; ++i) {
        unsigned p{i - 1};
        while (p && Q[p] < Q[i]) p = prev_greater[p];
        prev_greater[i] = p;
        ans *= i - p;
    }
    cout << ans.val() << endl;
    return 0;
}
